  const burden=rows.slice().sort((a,b)=>b.rent_to_salary_ratio_pct-a.rent_to_salary_ratio_pct).slice(0,15);
  new Chart(document.getElementById('rentBurdenTop'),{type:'bar',data:{labels:burden.map(r=>`${r.city} (${r.country})`),datasets:[{label:'Rent-to-Salary Ratio %',data:burden.map(r=>r.rent_to_salary_ratio_pct),backgroundColor:'#dc2626'}]},options:{indexAxis:'y',plugins:{title:{display:true,text:'Top 15 Cities by Rent Burden'}}}});
  new Chart(document.getElementById('salaryVsBurden'),{type:'scatter',data:{datasets:[{label:'Cities',data:rows.map(r=>({x:r.avg_monthly_net_salary_usd,y:r.rent_to_salary_ratio_pct})),backgroundColor:'#7c3aed'}]},options:{plugins:{title:{display:true,text:'Salary vs Rent Burden'}},scales:{x:{title:{display:true,text:'Avg Monthly Net Salary (USD)'}},y:{title:{display:true,text:'Rent-to-Salary Ratio %'}}}}});

  new Chart(document.getElementById('tierRadar'),{type:'radar',data:{labels:['Cost of Living','Rent Index','Purchasing Power','Rent-to-Salary %','Inflation %'],datasets:tiers.map((t,i)=>({label:`Tier ${t.tier}`,data:[t.avg_cost_of_living_index,t.avg_rent_index,t.avg_local_purchasing_power_index,t.avg_rent_to_salary_ratio_pct,t.avg_annual_inflation_rate_2025_pct],fill:true}))},options:{plugins:{title:{display:true,text:'Crisis Tier Indicator Profiles'}}}});
  new Chart(document.getElementById('tierBurden'),{type:'bar',data:{labels:tiers.map(t=>`Tier ${t.tier}`),datasets:[{label:'Avg Rent-to-Salary %',data:tiers.map(t=>t.avg_rent_to_salary_ratio_pct),backgroundColor:'#ef4444'},{label:'Avg Cost of Living Index',data:tiers.map(t=>t.avg_cost_of_living_index),backgroundColor:'#3b82f6'},{label:'Avg Purchasing Power',data:tiers.map(t=>t.avg_local_purchasing_power_index),backgroundColor:'#22c55e'},{label:'Avg Inflation %',data:tiers.map(t=>t.avg_annual_inflation_rate_2025_pct),backgroundColor:'#f59e0b'}]},options:{plugins:{title:{display:true,text:'Tier Averages Comparison'}}}});

