  new Chart(document.getElementById('oilColPp'),{type:'bar',data:{labels:oil.map(o=>o.oil_shock_exposure),datasets:[{label:'Avg Cost of Living Index',data:oil.map(o=>o.avg_cost_of_living_index),backgroundColor:'#2563eb'},{label:'Avg Purchasing Power',data:oil.map(o=>o.avg_local_purchasing_power_index),backgroundColor:'#16a34a'}]},options:{plugins:{title:{display:true,text:'Cost and Purchasing Power by Oil Exposure'}}}});
});
